-- | WebAssembly text format (WAT) code generator for Awsum 'Core'.
--
-- Produces human-readable WAT (S-expression syntax) used for
-- @awsum asm -t wasm@ output and snapshot tests.
-- The binary @.wasm@ is generated by 'Awsum.Codegen.WASM.Assemble'.
--
-- Design:
--   * All values are @i32@ (pointers into linear memory).
--   * Strings are length-prefixed: a 12-byte refcount header
--     ([flag | refcount | shape]) followed by an 8-byte length header
--     (utf8_bytes : i32 LE, utf16_units : i32 LE) followed by the UTF-8
--     payload, no NUL terminator. Pointers address the refcount header
--     start; the length fields sit at offsets 12/16 and the payload at 20.
--   * WASI provides I\/O: @fd_write@ for stdout, @args_get@ for CLI args.
--   * Per-size-bin freelist allocator (@__alloc_shaped@ pops; @__free_recursive@
--     pushes back after cascading through pointer fields per the shape header).
--   * @funcref@ table + @call_indirect@ — used by 'Awsum.LowerClosures'
--     dispatcher arms when a residual closure flows through a position
--     that survives 'Awsum.Defunctionalize'.
module Awsum.Codegen.WASM (codegenWASM) where

import Awsum.Core
import Awsum.HM (rowTag)
import Awsum.Syntax (Name, Type' (..), noSpan)
import Data.Bits (shiftR, (.&.))
import Data.ByteString qualified as BS
import Data.Char qualified as Char
import Data.Map.Strict qualified as Map
import Data.Set qualified as Set
import Data.Text qualified as T
import Relude

-- ════════════════════════════════════════════════════════════════════════════
-- Public API
-- ════════════════════════════════════════════════════════════════════════════

-- | Produce a complete WAT module from a Core program.
codegenWASM :: PreludeTags -> CoreProgram -> Text
codegenWASM ptags prog@(CoreProgram decls) =
  let (pool, _emptyOff, heapStart) = buildStringPool prog
      valNames = Set.fromList [n | CValDef n _ <- decls]
      funNames = Set.fromList [n | CFunDef n _ _ <- decls]
      arities = Map.fromList [(n, length as) | CFunDef n as _ <- decls]
      funDefs = [n | CFunDef n _ _ <- decls]
      tableMap = Map.fromList (zip funDefs [0 :: Int ..])
      indirectArities = collectIndirectArities (CoreProgram decls) funNames
      ctx =
        WasmCtx
          { wParams = Set.empty,
            wValDefs = valNames,
            wFunDefs = funNames,
            wArities = arities,
            wStringPool = pool,
            wTableMap = tableMap,
            wIndirectArities = indirectArities,
            wLocalExprs = Map.empty,
            wConDepth = 0
          }
   in T.intercalate
        "\n"
        [ header,
          imports,
          memory heapStart,
          global heapStart,
          dataSection pool,
          table (length funDefs),
          elemSection funDefs,
          typeDecls indirectArities,
          runtimeHelpers ptags (usedBuiltIns prog) (usesIntLit prog),
          T.intercalate "\n\n" (map (emitDecl ctx) decls),
          "",
          startFunc,
          ")"
        ]

-- ════════════════════════════════════════════════════════════════════════════
-- Context
-- ════════════════════════════════════════════════════════════════════════════

data WasmCtx = WasmCtx
  { wParams :: Set Text,
    wValDefs :: Set Text,
    wFunDefs :: Set Text,
    wArities :: Map Text Int,
    wStringPool :: Map Text Int,
    wTableMap :: Map Text Int,
    wIndirectArities :: Set Int,
    wLocalExprs :: Map Text Text, -- case-bound variable → inline WAT expression
    wConDepth :: Int -- nesting depth for $__con_N locals
  }

-- ════════════════════════════════════════════════════════════════════════════
-- String pool
-- ════════════════════════════════════════════════════════════════════════════

-- | Offset where string constants begin in linear memory.
scratchSize :: Int
scratchSize = 64

-- | Build a string pool with byte offsets. Each entry has a 4-byte
--   @i32 flag = 0@ prefix (literal marker for '$__free'), then the
--   existing 8-byte length header
--   (utf8_bytes : i32 LE, utf16_units : i32 LE), then the UTF-8
--   payload. The pool maps a string to its USER-POINTER — that is,
--   @flag_start + 4@. From the user pointer the layout is unchanged:
--   byte_count at +0, utf16 at +4, payload at +8 — so every existing
--   reader (concat / print / lengthCodePoints / parsers) keeps
--   working without offset shifts.
--
--   Always seeds "" so the empty string has a stable pool slot
--   regardless of which literals a program uses.
--   Returns (pool, empty_string_user_pointer, heap_start).
buildStringPool :: CoreProgram -> (Map Text Int, Int, Int)
buildStringPool (CoreProgram decls) =
  let strs = ordNub $ "" : concatMap stringsInDecl decls
      entrySize s = stringHeaderSize + byteLen s
      flagStartScan = scanl (+) scratchSize (map entrySize strs)
      -- 'flagStartScan' has length = len strs + 1; the first 'len strs'
      -- entries are the flag-byte starts of each string, the final
      -- entry is the byte just past the last payload (= heap start).
      flagStarts = take (length strs) flagStartScan
      userPtrs = map (+ 12) flagStarts
      pool = Map.fromList (zip strs userPtrs)
      emptyOff = fromMaybe (scratchSize + 4) (Map.lookup "" pool)
      heapStart = fromMaybe scratchSize $ viaNonEmpty Relude.last flagStartScan
   in (pool, emptyOff, heapStart)

-- | Byte length of a string's UTF-8 payload (excluding the header).
byteLen :: Text -> Int
byteLen = BS.length . encodeUtf8

-- | UTF-16 code unit count of a string. BMP code points contribute 1;
--   supplementary (>= U+10000) contribute 2 (surrogate pair).
utf16CountOfText :: Text -> Int
utf16CountOfText = T.foldl' (\n c -> n + if Char.ord c > 0xFFFF then 2 else 1) 0

-- | Size of the per-string header in linear memory. The allocator
--   header is 12 bytes (flag + refcount + shape) and sits in front
--   of the existing 8-byte length header. Total prefix: 12
--   (allocator header) + 4 (byte_count) + 4 (utf16) = 20 bytes
--   before the payload. The user pointer is @flag_start + 12@ —
--   readers still see byte_count at +0, utf16 at +4, payload at +8.
stringHeaderSize :: Int
stringHeaderSize = 20

stringsInDecl :: CDecl -> [Text]
stringsInDecl = \case
  CFunDef _ _ body -> stringsInExpr body
  CValDef _ rhs -> stringsInExpr rhs

stringsInExpr :: CExpr -> [Text]
stringsInExpr = \case
  CString s -> [s]
  CVar _ -> []
  CIntLit _ _ -> []
  CBuiltIn _ -> []
  CCon _ fields -> concatMap stringsInExpr fields
  CCase scrut alts -> stringsInExpr scrut <> concatMap (\(_, _, body) -> stringsInExpr body) alts
  CRow _ v -> stringsInExpr v
  CRowCase scrut alts -> stringsInExpr scrut <> concatMap (\(_, _, body) -> stringsInExpr body) alts
  CCall f xs -> stringsInExpr f <> concatMap stringsInExpr xs
  CLoop b -> stringsInExpr b
  CContinue xs -> concatMap stringsInExpr xs
  CDrop _ _ body -> stringsInExpr body
  CReuse _ _ fs -> concatMap stringsInExpr fs

-- | Collect arities used in indirect calls (CCall where callee is a param, not a known fun/prim).
collectIndirectArities :: CoreProgram -> Set Text -> Set Int
collectIndirectArities (CoreProgram decls) funNames =
  Set.fromList $ concatMap (collectInDecl funNames) decls
  where
    collectInDecl :: Set Text -> CDecl -> [Int]
    collectInDecl fns = \case
      CFunDef _ args body -> collectInExpr fns (Set.fromList args) body
      CValDef _ rhs -> collectInExpr fns Set.empty rhs

    collectInExpr :: Set Text -> Set Text -> CExpr -> [Int]
    collectInExpr fns params = \case
      CCall f xs ->
        let fromF = case f of
              CVar n | n `Set.member` params -> [length xs]
              _ -> []
            fromChildren = collectInExpr fns params f <> concatMap (collectInExpr fns params) xs
         in fromF <> fromChildren
      _ -> []

-- ════════════════════════════════════════════════════════════════════════════
-- Module sections (text)
-- ════════════════════════════════════════════════════════════════════════════

header :: Text
header =
  unlines
    [ ";; Awsum WASM codegen — WAT text format for inspection.",
      ";; Binary .wasm is generated by assembleWASM for execution.",
      "(module"
    ]

imports :: Text
imports =
  unlines
    [ "  (import \"wasi_snapshot_preview1\" \"fd_write\" (func $fd_write (param i32 i32 i32 i32) (result i32)))",
      "  (import \"wasi_snapshot_preview1\" \"args_sizes_get\" (func $args_sizes_get (param i32 i32) (result i32)))",
      "  (import \"wasi_snapshot_preview1\" \"args_get\" (func $args_get (param i32 i32) (result i32)))",
      -- 'fd_read' powers '$__stdinReadAll'. Signature: fd_read(fd, iovs,
      -- iovs_len, nread_out) -> errno. We pass fd=0 (stdin), a single
      -- iovec at a scratch address, and read into a growing buffer until
      -- nread returns 0 (EOF).
      "  (import \"wasi_snapshot_preview1\" \"fd_read\" (func $fd_read (param i32 i32 i32 i32) (result i32)))"
    ]

-- | Initial linear-memory pages must cover the scratch + data section
--   (literals are written at module-instantiate time, before any
--   'memory.grow' could run). Heap allocations live above 'heapStart'
--   and grow the memory dynamically through '__alloc'.
memory :: Int -> Text
memory heapStart =
  let initialPages = max 1 ((heapStart + wasmPageSize - 1) `div` wasmPageSize)
   in "  (memory (export \"memory\") " <> show initialPages <> ")"

-- | A WebAssembly memory page is 64 KiB.
wasmPageSize :: Int
wasmPageSize = 65536

global :: Int -> Text
global heapStart =
  T.intercalate
    "\n"
    [ "  (global $heap (mut i32) (i32.const " <> show heapStart <> "))",
      -- '$__wl_buf' / '$__wl_top' / '$__wl_cap' back
      -- '$__free_recursive''s cascade. Non-last children of cells
      -- with shape > 1 go onto this heap-backed buffer instead of
      -- being recursed via 'call $__free_recursive', so the
      -- system-stack footprint of the helper is O(1) independent
      -- of cascade shape. Awsum is single-threaded and helpers
      -- never call user code, so a single shared buffer is
      -- safe. Storage doubles on overflow (initial 16 entries);
      -- old buffers that land in a bin freelist class are
      -- recovered, larger ones (> 4096 bytes / 1024 entries) leak
      -- — total leak ≤ 2× current capacity, bounded by the
      -- program's actual cascade-frontier high-water mark.
      "  (global $__wl_buf (mut i32) (i32.const 0))",
      "  (global $__wl_top (mut i32) (i32.const 0))",
      "  (global $__wl_cap (mut i32) (i32.const 0))"
    ]

dataSection :: Map Text Int -> Text
dataSection pool
  | Map.null pool = ""
  | otherwise =
      T.intercalate "\n"
        $ map emitData (sortWith snd $ Map.toList pool)
  where
    -- The pool maps a string to its USER pointer (= flag_start + 12).
    -- The data-section write happens 12 bytes earlier so the
    -- allocator header (flag + refcount + shape) lands in front of
    -- the existing length header.
    emitData (s, userPtr) =
      "  (data (i32.const " <> show (userPtr - 12) <> ") " <> watLengthPrefixed s <> ")"

-- | Format a length-prefixed string for the WAT data section.
--   Layout: 12-byte header (@i32 flag = 0@, @i32 refcount = 0@,
--   @i32 shape = 0@; literal — flag=0 short-circuits inc/dec/free) +
--   8-byte string header (utf8_bytes, utf16_units, both little-endian
--   i32) + UTF-8 payload (no NUL terminator). 20 bytes of header
--   total; the user pointer is at @flag_start + 12@, so readers still
--   see byte_count at +0 and utf16 at +4.
watLengthPrefixed :: Text -> Text
watLengthPrefixed s =
  let bc = byteLen s
      uc = utf16CountOfText s
   in "\""
        <> i32LeEsc 0 -- flag
        <> i32LeEsc 0 -- refcount
        <> i32LeEsc 0 -- shape
        <> i32LeEsc bc
        <> i32LeEsc uc
        <> watEscape s
        <> "\""

-- | Escape an Int as 4 little-endian bytes in @\\XX@ form for WAT data.
i32LeEsc :: Int -> Text
i32LeEsc n =
  T.concat
    [ "\\" <> hexByte ((n `shiftR` (8 * i)) .&. 0xFF)
    | i <- [0 .. 3 :: Int]
    ]
  where
    hexByte :: Int -> Text
    hexByte b =
      let hi = b `div` 16
          lo = b `mod` 16
          hexChar x
            | x < 10 = chr (0x30 + x)
            | otherwise = chr (0x61 + x - 10)
       in toText [hexChar hi, hexChar lo]

-- | Escape a string for WAT syntax. Encodes the string to UTF-8 first
--   and emits each byte: ASCII printable bytes pass through, everything
--   else (including the multi-byte tail of every non-ASCII codepoint)
--   becomes a @\\XX@ hex pair.
watEscape :: Text -> Text
watEscape = T.concat . map escByte . BS.unpack . encodeUtf8
  where
    escByte b
      | b == 0x5C = "\\\\" -- backslash
      | b == 0x22 = "\\22" -- double quote
      | b == 0x0A = "\\0a" -- newline
      | b == 0x09 = "\\09" -- tab
      | b == 0x0D = "\\0d" -- carriage return
      | b == 0x00 = "\\00" -- nul
      | b >= 0x20 && b <= 0x7E = T.singleton (chr (fromIntegral b))
      | otherwise =
          let hi = b `div` 16
              lo = b `mod` 16
              hexChar x
                | x < 10 = chr (fromIntegral (0x30 + x))
                | otherwise = chr (fromIntegral (0x61 + x - 10))
           in "\\" <> toText [hexChar hi, hexChar lo]

table :: Int -> Text
table n
  | n == 0 = ""
  | otherwise = "  (table " <> show n <> " funcref)"

elemSection :: [Text] -> Text
elemSection fns
  | null fns = ""
  | otherwise =
      "  (elem (i32.const 0) " <> T.intercalate " " (map (\n -> "$" <> mangle n) fns) <> ")"

typeDecls :: Set Int -> Text
typeDecls arities
  | Set.null arities = ""
  | otherwise =
      T.intercalate "\n"
        $ map emitType (Set.toAscList arities)
  where
    emitType arity =
      "  (type $arity_"
        <> show arity
        <> " (func"
        <> (if arity > 0 then " (param" <> T.concat (replicate arity " i32") <> ")" else "")
        <> " (result i32)))"

-- ════════════════════════════════════════════════════════════════════════════
-- Runtime helpers
-- ════════════════════════════════════════════════════════════════════════════

-- | Emit only the runtime helpers referenced in Core. @__alloc@ /
--   @__memcpy@ are always needed (small infrastructure), the
--   higher-level helpers (@__concat@, @__print@, @__box_i32@,
--   @__show_i32@, @__predInt32@) are gated on usage.
runtimeHelpers :: PreludeTags -> Set Name -> Bool -> Text
runtimeHelpers ptags builtIns hasIntLit =
  let lns =
        filter
          (not . T.null)
          [ rtAlloc,
            rtFree,
            rtIncRef,
            rtFreeWorklistPush,
            rtFreeRecursive,
            rtMemcpy,
            if Set.member "concatString" builtIns then rtConcat ptags else "",
            if Set.member "internalStdoutPrint" builtIns then rtPrint ptags else "",
            if hasIntLit then rtBoxI32 else "",
            if any (`Set.member` builtIns) ["showInt32", "showUInt8"]
              then rtShowI32
              else "",
            if Set.member "showUInt32" builtIns then rtShowU32 else "",
            if Set.member "predInt32" builtIns then rtPredI32 ptags else "",
            if Set.member "predUInt8" builtIns then rtPredU8 ptags else "",
            if Set.member "predUInt32" builtIns then rtPredU32 ptags else "",
            if Set.member "succInt32" builtIns then rtSuccI32 ptags else "",
            if Set.member "succUInt8" builtIns then rtSuccU8 ptags else "",
            if Set.member "succUInt32" builtIns then rtSuccU32 ptags else "",
            if any (`Set.member` builtIns) ["eqInt32", "eqUInt8", "eqUInt32"] then rtEqI32 ptags else "",
            if Set.member "eqString" builtIns then rtEqString ptags else "",
            if Set.member "eqString" builtIns then rtMemcmp else "",
            if Set.member "addInt32" builtIns then rtAddI32 ptags else "",
            if Set.member "subInt32" builtIns then rtSubI32 ptags else "",
            if Set.member "mulInt32" builtIns then rtMulI32 ptags else "",
            if Set.member "negInt32" builtIns then rtNegI32 ptags else "",
            if Set.member "addUInt8" builtIns then rtAddU8 ptags else "",
            if Set.member "subUInt8" builtIns then rtSubU8 ptags else "",
            if Set.member "mulUInt8" builtIns then rtMulU8 ptags else "",
            if Set.member "addUInt32" builtIns then rtAddU32 ptags else "",
            if Set.member "subUInt32" builtIns then rtSubU32 ptags else "",
            if Set.member "mulUInt32" builtIns then rtMulU32 ptags else "",
            if Set.member "splitOnFirst" builtIns then rtSplitOnFirst ptags else "",
            -- '__splitOnFirst' computes utf16 prefixes for both halves via
            -- '__utf16_of_range', so emit the helper whenever splitOnFirst
            -- is referenced.
            if Set.member "splitOnFirst" builtIns then rtUtf16OfRange else "",
            if Set.member "parseInt32" builtIns then rtParseInt32 ptags else "",
            if Set.member "parseUInt8" builtIns then rtParseUInt8 ptags else "",
            if Set.member "parseUInt32" builtIns then rtParseUInt32 ptags else "",
            if Set.member "lengthUtf8Bytes" builtIns then rtLengthBytesAsUtf8 else "",
            if Set.member "lengthCodePoints" builtIns then rtLengthCodePoints else "",
            if Set.member "lengthUtf16CodeUnits" builtIns then rtLengthUtf16CodeUnits else "",
            -- '__entryArgEither' / '__getArgs' / '__stdinReadAll' are
            -- always emitted in the WASM text codegen because the binary
            -- assembler emits all runtime helpers unconditionally
            -- (fixed-arity function indices). Gating the text would
            -- diverge text/binary snapshots without changing the binary
            -- footprint. A future WASM-binary optimisation can drop them
            -- per-program; until then, text mirrors binary.
            rtEntryArgEither ptags,
            rtGetArgs ptags,
            rtStdinReadAll
          ]
   in T.intercalate "\n\n" lns

rtAlloc :: Text
rtAlloc =
  unlines
    [ ";; ──────────────────────────────────────────────────────────────",
      ";; Per-size-bin freelist allocator with 12-byte header.",
      ";;",
      ";; Each block carries a 12-byte header:",
      ";;   block[0..4]  = flag (size class for heap, 0 for literal)",
      ";;   block[4..8]  = refcount (1 on alloc, dec on drop, 0 → free)",
      ";;   block[8..12] = shape (#ptr fields starting at slot 1; 0 by",
      ";;                  default — strings/boxed/nullary keep it,",
      ";;                  CCon/CRow emit override it to arity)",
      ";; flag values:",
      ";;   flag == 0           — literal (data-section string), no reclaim",
      ";;   flag == 8|16|…|4096 — heap, size class encoded in flag",
      ";;   flag >  4096        — heap, too large for any bin (leaks on free)",
      ";; user_ptr = block + 12. Existing readers (byte_count at",
      ";; user_ptr+0, ADT tag at user_ptr+0, payload at user_ptr+8, …)",
      ";; keep working unchanged.",
      ";;",
      ";; Bin freelist heads live in linear memory at offsets 24, 28,",
      ";; 32, …, 60 (10 i32 slots for size classes 8, 16, 32, 64, 128,",
      ";; 256, 512, 1024, 2048, 4096). Memory is zero-initialised by the",
      ";; WASM runtime so all bins start empty. Bytes 0..19 stay",
      ";; reserved for WASI scratch (see '$__drop_tmp' comment).",
      ";;",
      ";; Free block layout: block[0..4] flag preserved across free→alloc;",
      ";; block[8..12] re-used to hold next-ptr in freelist while free.",
      ";; (Using slot 8 not slot 4 because refcount at slot 4 sits in the",
      ";; user-visible area and pollutes future user reads if not cleared.)",
      "  (func $__alloc (param $size i32) (result i32)",
      "    (return (call $__alloc_shaped (local.get $size) (i32.const 0))))",
      "  (func $__alloc_shaped (param $size i32) (param $shape i32) (result i32)",
      "    (local $rounded i32)",
      "    (local $bin_addr i32)",
      "    (local $head i32)",
      "    (local $ptr i32)",
      "    ;; Round up to next power-of-2 (min 8): 1 << (32 - clz(size - 1)).",
      "    (local.set $rounded",
      "      (i32.shl (i32.const 1)",
      "        (i32.sub (i32.const 32) (i32.clz (i32.sub (local.get $size) (i32.const 1))))))",
      "    (if (i32.lt_u (local.get $rounded) (i32.const 8))",
      "      (then (local.set $rounded (i32.const 8))))",
      "    ;; If rounded ≤ 4096 try popping the matching bin first.",
      "    (if (i32.le_u (local.get $rounded) (i32.const 4096))",
      "      (then",
      "        ;; bin_addr = 24 + (ctz(rounded) - 3) * 4",
      "        (local.set $bin_addr",
      "          (i32.add (i32.const 24)",
      "            (i32.shl (i32.sub (i32.ctz (local.get $rounded)) (i32.const 3)) (i32.const 2))))",
      "        (local.set $head (i32.load (local.get $bin_addr)))",
      "        (if (local.get $head)",
      "          (then",
      "            ;; Pop: bin head := next-ptr stashed in block[8..12] while",
      "            ;; the block was free. Flag at head[0] still equals",
      "            ;; 'rounded'. Re-initialise refcount=1, shape=$shape.",
      "            (i32.store (local.get $bin_addr)",
      "              (i32.load (i32.add (local.get $head) (i32.const 8))))",
      "            (i32.store (i32.add (local.get $head) (i32.const 4)) (i32.const 1))",
      "            (i32.store (i32.add (local.get $head) (i32.const 8)) (local.get $shape))",
      "            (return (i32.add (local.get $head) (i32.const 12)))))))",
      "    ;; Bump path: 4-byte aligned, store flag/refcount/shape header,",
      "    ;; grow memory on demand.",
      "    (local.set $ptr (i32.and (i32.add (global.get $heap) (i32.const 3)) (i32.const -4)))",
      "    (global.set $heap (i32.add (i32.add (local.get $ptr) (i32.const 12)) (local.get $rounded)))",
      "    (block $grow_done",
      "      (loop $grow_loop",
      "        (br_if $grow_done",
      "          (i32.le_u (global.get $heap)",
      "                    (i32.mul (memory.size) (i32.const 65536))))",
      "        (if (i32.eq (memory.grow (i32.const 1)) (i32.const -1))",
      "          (then (unreachable)))",
      "        (br $grow_loop)))",
      "    (i32.store (local.get $ptr) (local.get $rounded))",
      "    (i32.store (i32.add (local.get $ptr) (i32.const 4)) (i32.const 1))",
      "    (i32.store (i32.add (local.get $ptr) (i32.const 8)) (local.get $shape))",
      "    (i32.add (local.get $ptr) (i32.const 12)))"
    ]

rtFree :: Text
rtFree =
  unlines
    [ ";; '$__free' reads the 4-byte flag prefix at (p - 12):",
      ";;   flag == 0 → literal, no-op (safe to call on '@.empty' / pool ptr).",
      ";;   flag > 4096 → huge alloc, no bin can hold it, leak.",
      ";;   otherwise → push block onto bin[flag] freelist. Block's first",
      ";;     4 bytes (flag) are preserved; next-ptr is stored at slot 8 of",
      ";;     the user area (= p - 4 in absolute terms, since user starts",
      ";;     at block + 12 and we want to write at block + 8).",
      "  (func $__free (param $p i32)",
      "    (local $flag i32)",
      "    (local $bin_addr i32)",
      "    (local $cur i32)",
      "    (local.set $flag (i32.load (i32.sub (local.get $p) (i32.const 12))))",
      "    (if (i32.eqz (local.get $flag)) (then (return)))",
      "    (if (i32.gt_u (local.get $flag) (i32.const 4096)) (then (return)))",
      "    (local.set $bin_addr",
      "      (i32.add (i32.const 24)",
      "        (i32.shl (i32.sub (i32.ctz (local.get $flag)) (i32.const 3)) (i32.const 2))))",
      "    (local.set $cur (i32.load (local.get $bin_addr)))",
      "    (i32.store (i32.sub (local.get $p) (i32.const 4)) (local.get $cur))",
      "    (i32.store (local.get $bin_addr) (i32.sub (local.get $p) (i32.const 12))))"
    ]

-- | '$__inc_ref' bumps the refcount at @user_ptr - 8@. No-op
-- on literals (flag == 0): their refcount field stays at 0 and they
-- never reach '$__free'.
rtIncRef :: Text
rtIncRef =
  unlines
    [ "  (func $__inc_ref (param $p i32)",
      "    (local $flag i32)",
      "    (local.set $flag (i32.load (i32.sub (local.get $p) (i32.const 12))))",
      "    (if (i32.eqz (local.get $flag)) (then (return)))",
      "    (i32.store (i32.sub (local.get $p) (i32.const 8))",
      "      (i32.add (i32.load (i32.sub (local.get $p) (i32.const 8))) (i32.const 1))))"
    ]

-- | '$__free_worklist_push' appends @$p@ onto the global worklist
-- (see 'global $__wl_buf' / '$__wl_top' / '$__wl_cap'). On
-- overflow it doubles the buffer ('__alloc_shaped(new_cap * 4, 0)'
-- with content copied over; the old buffer is returned to its bin
-- via '$__free' if it fits any size class, otherwise it leaks —
-- see the comment on the globals). Used by '$__free_recursive' for
-- non-last cascade children so its system-stack footprint stays
-- O(1) regardless of cascade shape.
rtFreeWorklistPush :: Text
rtFreeWorklistPush =
  unlines
    [ "  (func $__free_worklist_push (param $p i32)",
      "    (local $top i32)",
      "    (local $cap i32)",
      "    (local $new_cap i32)",
      "    (local $new_buf i32)",
      "    (local $old_buf i32)",
      "    (local $i i32)",
      "    (local.set $top (global.get $__wl_top))",
      "    (local.set $cap (global.get $__wl_cap))",
      "    (if (i32.eq (local.get $top) (local.get $cap))",
      "      (then",
      "        (if (i32.eqz (local.get $cap))",
      "          (then (local.set $new_cap (i32.const 16)))",
      "          (else (local.set $new_cap (i32.shl (local.get $cap) (i32.const 1)))))",
      "        (local.set $new_buf",
      "          (call $__alloc_shaped (i32.shl (local.get $new_cap) (i32.const 2)) (i32.const 0)))",
      "        (local.set $old_buf (global.get $__wl_buf))",
      "        ;; Copy old worklist contents.",
      "        (local.set $i (i32.const 0))",
      "        (block $copy_break",
      "          (loop $copy_loop",
      "            (br_if $copy_break (i32.ge_u (local.get $i) (local.get $top)))",
      "            (i32.store",
      "              (i32.add (local.get $new_buf) (i32.shl (local.get $i) (i32.const 2)))",
      "              (i32.load",
      "                (i32.add (local.get $old_buf) (i32.shl (local.get $i) (i32.const 2)))))",
      "            (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "            (br $copy_loop)))",
      "        (if (local.get $old_buf)",
      "          (then (call $__free (local.get $old_buf))))",
      "        (global.set $__wl_buf (local.get $new_buf))",
      "        (global.set $__wl_cap (local.get $new_cap))))",
      "    (i32.store",
      "      (i32.add (global.get $__wl_buf) (i32.shl (local.get $top) (i32.const 2)))",
      "      (local.get $p))",
      "    (global.set $__wl_top (i32.add (local.get $top) (i32.const 1))))"
    ]

-- | '$__free_recursive' dec's the refcount at @user_ptr - 8@.
-- On hitting 0 it reads @shape@ (number of ptr fields starting at
-- slot 1, stored at @user_ptr - 4@) and cascades: non-last
-- children are pushed onto the global worklist (see
-- '$__free_worklist_push'); the last slot is taken as the new @$p$
-- in the outer loop and the current block is returned to its bin
-- via '$__free'. When the current cell needs no further work
-- (literal, refcount > 0, or shape == 0) the helper pops the next
-- pending pointer from the worklist; if the worklist is empty,
-- it returns. The system-stack footprint is O(1) regardless of
-- the cascade shape: deep frontiers grow the worklist (heap), not
-- the stack. Awsum immutability guarantees the cell graph is
-- acyclic, so the cascade terminates.
rtFreeRecursive :: Text
rtFreeRecursive =
  unlines
    [ "  (func $__free_recursive (param $p i32)",
      "    (local $flag i32)",
      "    (local $rc i32)",
      "    (local $shape i32)",
      "    (local $i i32)",
      "    (local $top i32)",
      "    (block $done",
      "      (loop $outer",
      "        (local.set $flag (i32.load (i32.sub (local.get $p) (i32.const 12))))",
      "        (block $next",
      "          (br_if $next (i32.eqz (local.get $flag)))",
      "          (local.set $rc",
      "            (i32.sub (i32.load (i32.sub (local.get $p) (i32.const 8))) (i32.const 1)))",
      "          (i32.store (i32.sub (local.get $p) (i32.const 8)) (local.get $rc))",
      "          (br_if $next (local.get $rc))",
      "          (local.set $shape (i32.load (i32.sub (local.get $p) (i32.const 4))))",
      "          (if (i32.eqz (local.get $shape))",
      "            (then",
      "              (call $__free (local.get $p))",
      "              (br $next)))",
      "          ;; Push non-last children (slots 1..shape-1) onto the worklist.",
      "          (local.set $i (i32.const 1))",
      "          (block $push_break",
      "            (loop $push_loop",
      "              (br_if $push_break (i32.ge_u (local.get $i) (local.get $shape)))",
      "              (call $__free_worklist_push",
      "                (i32.load",
      "                  (i32.add (local.get $p) (i32.shl (local.get $i) (i32.const 2)))))",
      "              (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "              (br $push_loop)))",
      "          ;; Last slot: consume iteratively as the new $p, free the",
      "          ;; current block, re-enter $outer with $p := child.",
      "          (local.set $i",
      "            (i32.load",
      "              (i32.add (local.get $p) (i32.shl (local.get $shape) (i32.const 2)))))",
      "          (call $__free (local.get $p))",
      "          (local.set $p (local.get $i))",
      "          (br $outer))",
      "        ;; Pop the next pending pointer; exit on empty.",
      "        (local.set $top (global.get $__wl_top))",
      "        (br_if $done (i32.eqz (local.get $top)))",
      "        (local.set $top (i32.sub (local.get $top) (i32.const 1)))",
      "        (global.set $__wl_top (local.get $top))",
      "        (local.set $p",
      "          (i32.load",
      "            (i32.add (global.get $__wl_buf) (i32.shl (local.get $top) (i32.const 2)))))",
      "        (br $outer))))"
    ]

rtMemcpy :: Text
rtMemcpy =
  unlines
    [ "  (func $__memcpy (param $dst i32) (param $src i32) (param $len i32)",
      "    (local $i i32)",
      "    (local.set $i (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        (br_if $break (i32.ge_u (local.get $i) (local.get $len)))",
      "        (i32.store8 (i32.add (local.get $dst) (local.get $i))",
      "                    (i32.load8_u (i32.add (local.get $src) (local.get $i))))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $loop))))"
    ]

-- | Byte-by-byte equality on two ranges. Returns 1 if all 'len' bytes
--   match, 0 on the first mismatch. Used by '__eqString' after the
--   byte-count short-circuit. Different shape from libc 'memcmp', which
--   returns a tri-state ordering; for string equality only the boolean
--   answer is needed and an early-out loop is cheaper.
rtMemcmp :: Text
rtMemcmp =
  unlines
    [ "  (func $__memcmp (param $a i32) (param $b i32) (param $len i32) (result i32)",
      "    (local $i i32)",
      "    (local.set $i (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        (br_if $break (i32.ge_u (local.get $i) (local.get $len)))",
      "        (if (i32.ne (i32.load8_u (i32.add (local.get $a) (local.get $i)))",
      "                    (i32.load8_u (i32.add (local.get $b) (local.get $i))))",
      "          (then (return (i32.const 0))))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $loop)))",
      "    (i32.const 1))"
    ]

-- | eqString : String -> String -> Bool. Strings are length-prefixed
--   (byte_count at offset 0, utf16_count at offset 4, payload at offset
--   8). Strict-UTF-16 invariant gives equal UTF-16 ⇔ equal UTF-8 bytes,
--   so byte_count check + '__memcmp' on the payload is sufficient — no
--   UTF-16 reconstruction needed. Returns a one-slot Bool container
--   ([tag]). True=0, False=1 matches declaration order in
--   `type Bool = True | False`.
rtEqString :: PreludeTags -> Text
rtEqString ptags =
  unlines
    [ "  (func $__eqString (param $a i32) (param $b i32) (result i32)",
      "    (local $ba i32) (local $bb i32) (local $cell i32) (local $eq i32)",
      "    (local.set $ba (i32.load (local.get $a)))",
      "    (local.set $bb (i32.load (local.get $b)))",
      "    (local.set $cell (call $__alloc (i32.const 4)))",
      "    (if (i32.eq (local.get $ba) (local.get $bb))",
      "      (then",
      "        (local.set $eq (call $__memcmp",
      "          (i32.add (local.get $a) (i32.const 8))",
      "          (i32.add (local.get $b) (i32.const 8))",
      "          (local.get $ba)))",
      "        (if (local.get $eq)",
      "          (then (i32.store (local.get $cell) (i32.const " <> tShow (ptTrue ptags) <> ")))",
      "          (else (i32.store (local.get $cell) (i32.const " <> tShow (ptFalse ptags) <> ")))))",
      "      (else",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptFalse ptags) <> "))))",
      "    (call $__free_recursive (local.get $a))",
      "    (call $__free_recursive (local.get $b))",
      "    (local.get $cell))"
    ]

-- | Counts UTF-16 code units in a UTF-8 byte range. Used by
--   '__splitOnFirst' to compute the utf16 prefix for the two output
--   substrings. Walks bytes, treating only non-continuation bytes as
--   characters; bytes whose top bits are @11110xxx@ (4-byte UTF-8 lead,
--   i.e. supplementary plane) contribute 2 UTF-16 code units, all
--   others contribute 1.
rtUtf16OfRange :: Text
rtUtf16OfRange =
  unlines
    [ "  (func $__utf16_of_range (param $p i32) (param $len i32) (result i32)",
      "    (local $i i32) (local $n i32) (local $b i32)",
      "    (local.set $i (i32.const 0))",
      "    (local.set $n (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        (br_if $break (i32.ge_u (local.get $i) (local.get $len)))",
      "        (local.set $b (i32.load8_u (i32.add (local.get $p) (local.get $i))))",
      "        (if (i32.ne (i32.and (local.get $b) (i32.const 192)) (i32.const 128))",
      "          (then",
      "            (if (i32.eq (i32.and (local.get $b) (i32.const 248)) (i32.const 240))",
      "              (then (local.set $n (i32.add (local.get $n) (i32.const 2))))",
      "              (else (local.set $n (i32.add (local.get $n) (i32.const 1)))))))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $loop)))",
      "    (local.get $n))"
    ]

-- | __concat implements 'BuiltIn.concatString' on the length-prefixed
--   string layout. Cap-check is O(1) (load both UTF-16 lengths from
--   headers, sum, compare) — no byte scan, no short-circuit needed.
--   The cap value (134217728 = 2^27) must stay in sync with
--   'maxStringLengthUtf16CodeUnits' in 'stdlib/Prelude.aww'.
--
--   Output: alloc(8 + ba + bb), write byte/utf16 sums in the header,
--   memcpy a's payload then b's payload to offset 8.
rtConcat :: PreludeTags -> Text
rtConcat ptags =
  unlines
    [ "  (func $__concat (param $a i32) (param $b i32) (result i32)",
      "    (local $ba i32) (local $bb i32) (local $ua i32) (local $ub i32)",
      "    (local $usum i32) (local $bsum i32)",
      "    (local $stl i32) (local $cell i32) (local $buf i32)",
      "    (local.set $ba (i32.load (local.get $a)))",
      "    (local.set $ua (i32.load offset=4 (local.get $a)))",
      "    (local.set $bb (i32.load (local.get $b)))",
      "    (local.set $ub (i32.load offset=4 (local.get $b)))",
      "    (local.set $usum (i32.add (local.get $ua) (local.get $ub)))",
      "    (if (i32.gt_u (local.get $usum) (i32.const 134217728))",
      "      (then",
      "        (local.set $stl (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $stl) (i32.const " <> tShow (ptStringTooLong ptags) <> "))",
      "        (local.set $cell (call $__alloc_shaped (i32.const 8) (i32.const 1)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $stl)))",
      "      (else",
      "        (local.set $bsum (i32.add (local.get $ba) (local.get $bb)))",
      "        (local.set $buf (call $__alloc (i32.add (local.get $bsum) (i32.const 8))))",
      "        (i32.store (local.get $buf) (local.get $bsum))",
      "        (i32.store offset=4 (local.get $buf) (local.get $usum))",
      "        (call $__memcpy",
      "          (i32.add (local.get $buf) (i32.const 8))",
      "          (i32.add (local.get $a) (i32.const 8))",
      "          (local.get $ba))",
      "        (call $__memcpy",
      "          (i32.add (local.get $buf) (i32.add (i32.const 8) (local.get $ba)))",
      "          (i32.add (local.get $b) (i32.const 8))",
      "          (local.get $bb))",
      "        (local.set $cell (call $__alloc_shaped (i32.const 8) (i32.const 1)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $buf))))",
      "    (call $__free_recursive (local.get $a))",
      "    (call $__free_recursive (local.get $b))",
      "    (local.get $cell))"
    ]

-- | 'show' specialized to 'Int -> Text' so call sites that interpolate
--   tag values stay readable without explicit type signatures.
tShow :: Int -> Text
tShow = show

-- | __print: low-level platform primitive driven by the prelude's
--   `runIO` via `BuiltIn.internalStdoutPrint`. Returns a Unit value
--   (alloc(4); store tag 0) so the surrounding `case … of Unit ->
--   next` arm in `runIO` dispatches through the standard CCase tag
--   check.
rtPrint :: PreludeTags -> Text
rtPrint ptags =
  unlines
    [ "  (func $__print (param $s i32) (result i32)",
      "    (local $len i32)",
      "    (local $unit i32)",
      -- length-prefixed: byte_count at offset 0, payload starts at offset 8.
      "    (local.set $len (i32.load (local.get $s)))",
      "    (i32.store (i32.const 0) (i32.add (local.get $s) (i32.const 8)))",
      "    (i32.store (i32.const 4) (local.get $len))",
      "    (drop (call $fd_write (i32.const 1) (i32.const 0) (i32.const 1) (i32.const 8)))",
      -- Build Unit value: alloc(4) + store Unit tag at offset 0.
      "    (local.set $unit (call $__alloc (i32.const 4)))",
      "    (i32.store (local.get $unit) (i32.const " <> tShow (ptUnit ptags) <> "))",
      "    (call $__free_recursive (local.get $s))",
      "    (local.get $unit))"
    ]

-- | Box a 32-bit value as a heap cell; the returned pointer is the uniform
--   representation of both Int32 and UInt8 at runtime (UInt8 values 0..255
--   fit trivially in 32 bits, which avoids a second boxing variant).
rtBoxI32 :: Text
rtBoxI32 =
  unlines
    [ "  (func $__box_i32 (param $v i32) (result i32)",
      "    (local $p i32)",
      "    (local.set $p (call $__alloc (i32.const 4)))",
      "    (i32.store (local.get $p) (local.get $v))",
      "    (local.get $p))"
    ]

-- | Render a boxed integer as a length-prefixed string.
--
--   The input pointer holds a 32-bit value; we treat it as signed (@i32.lt_s@)
--   for the minus-sign check. UInt8 values 0..255 are always positive in the
--   signed interpretation, so the same routine renders them correctly.
--
--   Algorithm: alloc(24) = 8-byte header + 16-byte scratch (offsets 8..23).
--   Write digits backwards starting at offset 23 and moving left; the leftmost
--   character ends up at offset @pos+1@, the rightmost at offset 23.
--   Worst case is @-2147483648@ (11 chars) so 16 scratch bytes are sufficient.
--   After rendering, copy the rendered run forward to start at offset 8 (the
--   payload), then write byte_count and utf16_count into the header.
--
--   Negation of @INT_MIN@ is a no-op in two's complement, but since we use
--   @i32.div_u@ / @i32.rem_u@ on the magnitude, the unsigned reading of
--   @0x80000000@ is @2147483648@ — the correct magnitude.
rtShowI32 :: Text
rtShowI32 =
  unlines
    [ "  (func $__show_i32 (param $p i32) (result i32)",
      "    (local $v i32) (local $buf i32) (local $pos i32) (local $neg i32) (local $mag i32) (local $digit i32) (local $blen i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (local.set $buf (call $__alloc (i32.const 24)))",
      "    (local.set $pos (i32.const 23))",
      "    (if (i32.lt_s (local.get $v) (i32.const 0))",
      "      (then",
      "        (local.set $neg (i32.const 1))",
      "        (local.set $mag (i32.sub (i32.const 0) (local.get $v))))",
      "      (else",
      "        (local.set $neg (i32.const 0))",
      "        (local.set $mag (local.get $v))))",
      "    (if (i32.eqz (local.get $mag))",
      "      (then",
      "        (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.const 48))",
      "        (local.set $pos (i32.sub (local.get $pos) (i32.const 1))))",
      "      (else",
      "        (block $done",
      "          (loop $loop",
      "            (br_if $done (i32.eqz (local.get $mag)))",
      "            (local.set $digit (i32.rem_u (local.get $mag) (i32.const 10)))",
      "            (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.add (local.get $digit) (i32.const 48)))",
      "            (local.set $pos (i32.sub (local.get $pos) (i32.const 1)))",
      "            (local.set $mag (i32.div_u (local.get $mag) (i32.const 10)))",
      "            (br $loop)))))",
      "    (if (local.get $neg)",
      "      (then",
      "        (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.const 45))",
      "        (local.set $pos (i32.sub (local.get $pos) (i32.const 1)))))",
      -- byte_count = 23 - pos. ASCII only → utf16_count == byte_count.
      "    (local.set $blen (i32.sub (i32.const 23) (local.get $pos)))",
      "    (call $__memcpy (i32.add (local.get $buf) (i32.const 8))",
      "                    (i32.add (local.get $buf) (i32.add (local.get $pos) (i32.const 1)))",
      "                    (local.get $blen))",
      "    (i32.store (local.get $buf) (local.get $blen))",
      "    (i32.store offset=4 (local.get $buf) (local.get $blen))",
      "    (call $__free_recursive (local.get $p))",
      "    (local.get $buf))"
    ]

-- | predInt32: Int32 -> Either UnderflowError Int32.
--   Containers follow the uniform WASM layout [i32 tag at offset 0,
--   i32 fields at offsets 4, 8, ...]. Tags: Left=0, Right=1,
--   UnderflowError=0. Returns `Left UnderflowError` on INT32_MIN,
--   `Right (v - 1)` otherwise.
rtPredI32 :: PreludeTags -> Text
rtPredI32 ptags =
  unlines
    [ "  (func $__predInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (i32.eq (local.get $v) (i32.const -2147483648))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const " <> tShow (ptUnderflowError ptags) <> "))",
      "        (local.set $cell (call $__alloc_shaped (i32.const 8) (i32.const 1)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue)))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc_shaped (i32.const 8) (i32.const 1)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))))",
      "    (call $__free_recursive (local.get $p))",
      "    (local.get $cell))"
    ]

-- | predUInt8: UInt8 -> Either UnderflowError UInt8.
--   Mirrors 'rtPredI32' but checks against 0 and subtracts without
--   masking — (v - 1) is in 0..254 when v >= 1, so it stays in UInt8
--   range naturally. Container layout and tag assignment match
--   'rtPredI32' exactly.
rtPredU8 :: PreludeTags -> Text
rtPredU8 ptags =
  unlines
    [ "  (func $__predUInt8 (param $p i32) (result i32)",
      "    (local $v i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (i32.eqz (local.get $v))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const " <> tShow (ptUnderflowError ptags) <> "))",
      "        (local.set $cell (call $__alloc_shaped (i32.const 8) (i32.const 1)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptLeft ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue)))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc_shaped (i32.const 8) (i32.const 1)))",
      "        (i32.store (local.get $cell) (i32.const " <> tShow (ptRight ptags) <> "))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))))",
      "    (call $__free_recursive (local.get $p))",
      "    (local.get $cell))"
