      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.add (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc_shaped (i32.const 8) (i32.const 1)))",
